namespace
{
// XLWebEngineUI: optional FXC is loaded only from engine/system absolute paths.
static HMODULE xlLoadOptionalCompiler()
{
    HMODULE owner = nullptr;
    wchar_t path[32768]{};
    if (GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS |
                          GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
                          reinterpret_cast<LPCWSTR>(&xlLoadOptionalCompiler), &owner))
    {
        const DWORD length = GetModuleFileNameW(owner, path, 32768);
        if (length && length < 32768)
        {
            wchar_t *slash = wcsrchr(path, L'\\');
            if (slash && (slash - path) + 21 < 32768)
            {
                wcscpy(slash + 1, L"d3dcompiler_47.dll");
                if (HMODULE module = LoadLibraryW(path)) return module;
            }
        }
    }
    const UINT length = GetSystemDirectoryW(path, 32768);
    if (!length || length + 22 >= 32768) return nullptr;
    wcscat(path, L"\\d3dcompiler_47.dll");
    return LoadLibraryW(path);
}

